import React, { useState } from 'react';
import axios from 'axios';
import '../styles/Login.css';

const Register = () => {
  const [formData, setFormData] = useState({
    nom: '',
    prenom: '',
    email: '',
    mot_de_passe: '',
    telephone: '',
    numero_tva: '',
    adresse: '',
    ville: '',
    code_postal: '',
    role: 'admin'
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await axios.post('http://localhost:8000/api/auth/register', formData);
      localStorage.setItem('token', response.data.token);
      localStorage.setItem('user', JSON.stringify(response.data.data));
      window.location.href = '/dashboard';
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-container">
      <div className="login-box" style={{maxWidth: '500px'}}>
        <h1>Système OMC</h1>
        <h2>Créer mon compte</h2>
        {error && <div className="error-message">{error}</div>}
        <form onSubmit={handleSubmit}>
          <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px'}}>
            <div className="form-group">
              <label>Nom *</label>
              <input type="text" name="nom" value={formData.nom} onChange={handleChange} required />
            </div>
            <div className="form-group">
              <label>Prénom *</label>
              <input type="text" name="prenom" value={formData.prenom} onChange={handleChange} required />
            </div>
          </div>
          <div className="form-group">
            <label>Email *</label>
            <input type="email" name="email" value={formData.email} onChange={handleChange} required />
          </div>
          <div className="form-group">
            <label>Mot de passe *</label>
            <input type="password" name="mot_de_passe" value={formData.mot_de_passe} onChange={handleChange} required />
          </div>
          <div className="form-group">
            <label>Téléphone</label>
            <input type="tel" name="telephone" value={formData.telephone} onChange={handleChange} />
          </div>
          <div className="form-group">
            <label>Numéro de TVA</label>
            <input type="text" name="numero_tva" value={formData.numero_tva} onChange={handleChange} placeholder="BE0123456789" />
          </div>
          <div className="form-group">
            <label>Adresse</label>
            <input type="text" name="adresse" value={formData.adresse} onChange={handleChange} />
          </div>
          <div style={{display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '10px'}}>
            <div className="form-group">
              <label>Code postal</label>
              <input type="text" name="code_postal" value={formData.code_postal} onChange={handleChange} />
            </div>
            <div className="form-group">
              <label>Ville</label>
              <input type="text" name="ville" value={formData.ville} onChange={handleChange} />
            </div>
          </div>
          <button type="submit" disabled={loading} style={{marginTop: '15px'}}>
            {loading ? 'Création...' : 'Créer mon compte'}
          </button>
        </form>
        <p className="register-link">Déjà un compte ? <a href="/login">Se connecter</a></p>
      </div>
    </div>
  );
};

export default Register;
